(49811, 'Genesis 46:23', 'Genesis', 46, 23, 'دان او د هغه زوی حوشیم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis46_verse_23.mp3', '', 1761754199, 1761754199),
(49812, 'Genesis 46:24', 'Genesis', 46, 24, 'نفتالي او د هغه زامن: یحصییل، جوني، یصر او شلیم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis46_verse_24.mp3', '', 1761754199, 1761754199),
(49813, 'Genesis 46:25', 'Genesis', 46, 25, 'دغه اووه تنه د یعقوب اولاده وه چې د بلهې څخه پیدا شوي وو او بلهه هغه وینځه وه چې لابان خپلې لور راحیل ته ورکړې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis46_verse_25.mp3', '', 1761754199, 1761754199),
(49814, 'Genesis 46:26', 'Genesis', 46, 26, 'د هغو کسانو شمېر چې په خپله د یعقوب د نسل څخه وو او د هغه سره مصر ته تللي وو، ټول شپږشپېته تنه وو چې په هغو کې د یعقوب د زامنو ښځې شاملې نه وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis46_verse_26.mp3', '', 1761754199, 1761754199),
(49815, 'Genesis 46:27', 'Genesis', 46, 27, 'د یوسف زامن چې په مصر کې پیدا شول دوه تنه وو. نو د یعقوب د کورنۍ غړي چې مصر ته تللي وو ټول اویا تنه وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis46_verse_27.mp3', '', 1761754199, 1761754199),
(49816, 'Genesis 46:28', 'Genesis', 46, 28, 'یعقوب یهودا د ځان څخه مخکې یوسف ته ولېږه چې د جوشن لاره ورته وروښایي. کله چې هغوی د جوشن سیمې ته ورسېدل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis46_verse_28.mp3', '', 1761754199, 1761754199),
(49817, 'Genesis 46:29', 'Genesis', 46, 29, 'یوسف خپله جنګي ګاډۍ تیاره کړه او جوشن ته د خپل پلار د لیدلو دپاره روان شو او څنګه چې یې هغه ولیده، په غېږ کې یې ونیوه او ډېر یې وژړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis46_verse_29.mp3', '', 1761754199, 1761754199),
(49818, 'Genesis 46:30', 'Genesis', 46, 30, 'یعقوب یوسف ته وویل: «اوس زه مرګ ته تیار یم، ځکه چې ته مې ولیدلې او پوه شوم چې تر‌اوسه پورې ژوندی یې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis46_verse_30.mp3', '', 1761754199, 1761754199),
(49819, 'Genesis 46:31', 'Genesis', 46, 31, 'نو بیا یوسف خپلو ورونو او د خپل پلار کورنۍ ته وویل: «زه ځم او د فرعون سره خبرې کوم او ورته به ووایم چې زما ورونه او زما د پلار ټوله کورنۍ چې په کنعان کې اوسېدل، ماته راغلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis46_verse_31.mp3', '', 1761754199, 1761754199),
(49820, 'Genesis 46:32', 'Genesis', 46, 32, 'دا خلک شپانه دي او حیوانات ساتي او خپلې رمې، پادې او هرڅه چې یې درلودل د ځان سره یې راوړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis46_verse_32.mp3', '', 1761754199, 1761754199),
(49821, 'Genesis 46:33', 'Genesis', 46, 33, 'کله چې فرعون تاسو راوغواړي او پوښتنه درڅخه وکړي چې تاسو څه کسب کوئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis46_verse_33.mp3', '', 1761754199, 1761754199),
(49822, 'Genesis 46:34', 'Genesis', 46, 34, 'نو تاسو باید ځواب ورکړئ چې مونږ د هلکتوب څخه د خپلو نیکونو په شان تر‌اوسه پورې حیوانات ساتو. نو بیا به تاسو ته اجازه درکړي چې د جوشن په سیمه کې واوسېږئ.» یوسف دا خبره په دې خاطر وکړه چې مصریان د شپنو څخه کرکه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis46_verse_34.mp3', '', 1761754199, 1761754199),
(49823, 'Hosea 11:1', 'Hosea', 11, 1, 'څښتن وایي: اسراییل چې کله ؤ ماشوم راباندې ګران ؤ لکه د زوی په شان او ما د مصر نه راوغوښت هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea11_verse_1.mp3', '', 1761754199, 1761754199),
(49824, 'Hosea 11:2', 'Hosea', 11, 2, 'خو څومره چې ما کاوه اواز هغه ته لېرې کېده هومره زما نه هغه بعل بتانو ته کوله قرباني زما قوم سوځولې خوشبویي هغوی بتانو ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea11_verse_2.mp3', '', 1761754199, 1761754199),
(49825, 'Hosea 11:3', 'Hosea', 11, 3, 'خو بیاهم زه وم چې مې زده کړ اسراییل ته د ګرځېدلو چل هغه مې ونیوه د لاسونو څخه خو هغه پوه نه شو چې ما پام کاوه هغه باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea11_verse_3.mp3', '', 1761754199, 1761754199),
(49826, 'Hosea 11:4', 'Hosea', 11, 4, 'ما د مینې او محبت په رسۍ راکش کړل هغوی خپل ځان ته ما را‌اوچت کړ جغ چې هغوی وکړي خوراک زه ورټیټ شومه هغوی ته او خواړه مې ورکړل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea11_verse_4.mp3', '', 1761754199, 1761754199),
(49827, 'Hosea 11:5', 'Hosea', 11, 5, 'هغوی باید مصر ته ورستانه نه شي، خو آشوریان به په هغوی باندې حکومت کوي، ځکه چې هغوی نه غواړي چې بېرته زما خواته راوګرځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea11_verse_5.mp3', '', 1761754199, 1761754199),
(49828, 'Hosea 11:6', 'Hosea', 11, 6, 'جنګ به لکه د توفان په شان د هغوی ښارونو ته راځي او د ښار دروازې به ماتې کړي. جنګ به زما خلک برباد کړي، ځکه چې هغوی به د خپلو بدو دسیسو له امله له منځه لاړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea11_verse_6.mp3', '', 1761754199, 1761754199),
(49829, 'Hosea 11:7', 'Hosea', 11, 7, 'زما خلکو پرېکړه کړې ده چې د هغه خدای په خاطر ما رد کړي چې دوی فکر کوي هغه ډېر قوي دی، خو هغه مرسته نه شي کولی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea11_verse_7.mp3', '', 1761754199, 1761754199),
(49830, 'Hosea 11:8', 'Hosea', 11, 8, 'ای اسراییله، څنګه کولی شم چې تا پرېږدم؟ څنګه کولای شم چې دې تسلیم کړم چاته؟ کله کولای شم زه چې کړم تباه تا لکه ښار د ادمه؟ یا تا سره کار وکړم په شان د زبوییم د ښار؟ زړه مې نه غواړي چې وکړمه زه داسې کار ځکه چې ستا سره کړمه ډېره زیاته مینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea11_verse_8.mp3', '', 1761754199, 1761754199),
(49831, 'Hosea 11:9', 'Hosea', 11, 9, 'د خپل سخت قهر په وخت کې به زه درنه کړم سزا زه به بیا نه کړم اسراییل تباه ځکه چې خدای یمه، انسان نه یمه سپېڅلی ذات یم او تا سره مل یمه زه زه به رانه شم په غضب تا ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea11_verse_9.mp3', '', 1761754199, 1761754199),
(49832, 'Hosea 11:10', 'Hosea', 11, 10, 'کله چې زه په خپلو خلکو باندې لکه د زمري په شان وغورېږم، نو زما غوره شوی قوم به ولړزیږي. هغوی به زما پیروي وکړي. هغوی به په وېره د لوېدیځې خوا نه ماته راشي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea11_verse_10.mp3', '', 1761754199, 1761754199),
(49833, 'Hosea 11:11', 'Hosea', 11, 11, 'هغوی به له وېرې د مصر نه د مرغانو په شان والوزي او د آشور نه به د کوترو په شان راشي. هغوی به بېرته خپلو کورونو ته راولم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea11_verse_11.mp3', '', 1761754199, 1761754199),
(49834, 'Hosea 11:12', 'Hosea', 11, 12, 'د اسراییلو خلک په دروغو او چل سره زما څخه راتاو شوي دي او د یهودا خلک لا تر‌اوسه پورې زما په وړاندې چې وفادار او سپېڅلی خدای یم، سرکښي کوي. ما څښتن داسې ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea11_verse_12.mp3', '', 1761754199, 1761754199),
(49835, 'Genesis 3:1', 'Genesis', 3, 1, 'د هغو ټولو وحشي حیواناتو د ډلې څخه چې څښتن خدای جوړ کړي وو، مار ډېر مکرجن ؤ. یوه ورځ هغه ښځې ته راغی او پوښتنه یې ترې وکړه: «ایا په رښتیا خدای تاسو ته ویلي دي چې په باغ کې د هېڅ یوې ونې مېوه ونه خورئ؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis3_verse_1.mp3', '', 1761754199, 1761754199),
(49836, 'Genesis 3:2', 'Genesis', 3, 2, 'ښځې ځواب ورکړ: «خدای ویلي دي چې مونږ کولای شو د باغ د ټولو ونو د مېوو څخه وخورو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis3_verse_2.mp3', '', 1761754199, 1761754199),
(49837, 'Genesis 3:3', 'Genesis', 3, 3, 'بې له هغې ونې څخه چې د باغ په منځ کې ده. هغه مونږ ته ویلي دي چې د هغې ونې مېوه مه خورئ او حتی هغې ته لاس هم مه وروړئ، که داسې مو وکړل، نو تاسو به مړه شئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis3_verse_3.mp3', '', 1761754199, 1761754199),
(49838, 'Genesis 3:4', 'Genesis', 3, 4, 'مار ښځې ته وویل: «ډاډه اوسئ، تاسو به مړه نه شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis3_verse_4.mp3', '', 1761754199, 1761754199),
(49839, 'Genesis 3:5', 'Genesis', 3, 5, 'خدای پوهیږي چې که چېرې تاسو د دې ونې مېوه وخورئ، نو ستاسو سترګې به خلاصې شي او تاسو به د خدای په شان شئ او په ښو او بدو شیانو باندې به پوه شئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis3_verse_5.mp3', '', 1761754199, 1761754199),
(49840, 'Genesis 3:6', 'Genesis', 3, 6, 'ښځې ونې ته په ځیر وکتل او هغه ونه د هغې په نظر کې ښکلې او مېوه یې خوندوره ښکاره شوه، فکر یې وکړ چې دا ونه به د پوهې د حاصلولو دپاره څومره ښه وي. نو هغه مېوه یې راواخیستله او ویې خوړله او خپل مېړه ته یې چې د هغې سره ؤ، هم ورکړه او هغه هم وخوړله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis3_verse_6.mp3', '', 1761754199, 1761754199),
(49841, 'Genesis 3:7', 'Genesis', 3, 7, 'په هماغه وخت کې د هغوی سترګې وغړېدلې او پوه شول چې لوڅ دي، نو د انځر پاڼې یې یو تر بله سره وګنډلې او ځانونه یې ورباندې پټ کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis3_verse_7.mp3', '', 1761754199, 1761754199),
(49842, 'Genesis 3:8', 'Genesis', 3, 8, 'مازدیګر کله چې باد لګېده، آدم او د هغه ښځې د څښتن خدای د قدمونو اواز واورېد چې په باغ کې ګرځېده. هغوی ووېرېدل او ځانونه یې د ونو ترشا پټ کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis3_verse_8.mp3', '', 1761754199, 1761754199),
(49843, 'Genesis 3:9', 'Genesis', 3, 9, 'څښتن خدای په آدم باندې غږ وکړ: «ته چېرته یې؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis3_verse_9.mp3', '', 1761754199, 1761754199),
(49844, 'Genesis 3:10', 'Genesis', 3, 10, 'هغه ځواب ورکړ: «په باغ کې مې ستا د قدمونو اواز واورېد، ووېرېدم او خپل ځان مې پټ کړ، ځکه چې لوڅ وم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis3_verse_10.mp3', '', 1761754199, 1761754199),
(49845, 'Genesis 3:11', 'Genesis', 3, 11, 'خدای ورڅخه پوښتنه وکړه: «چا درته وویل چې ته لوڅ یې؟ ایا د هغې ونې مېوه دې خوړلې ده چې ما درته ویلي وو چې هغه مه خوره؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis3_verse_11.mp3', '', 1761754199, 1761754199),
(49846, 'Genesis 3:12', 'Genesis', 3, 12, 'آدم وویل: «هغې ښځې چې تا ماته راکړې ده، دا مېوه راکړه او ما وخوړله.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis3_verse_12.mp3', '', 1761754199, 1761754199),
(49847, 'Genesis 3:13', 'Genesis', 3, 13, 'نو څښتن خدای د ښځې څخه پوښتنه وکړه: «تا څه وکړل؟» ښځې ځواب ورکړ: «مار زه وغولولم او ما هغه مېوه وخوړله.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis3_verse_13.mp3', '', 1761754199, 1761754199),
(49848, 'Genesis 3:14', 'Genesis', 3, 14, 'نو څښتن خدای مار ته وویل: «په دې سبب چې تا دا کار کړی دی، ته به د نورو ټولو کورني او وحشي حیواناتو څخه زیات لعنتي یې! ټول عمر به په سینه باندې ښویېږې او خاورې به خورې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis3_verse_14.mp3', '', 1761754199, 1761754199),
(49849, 'Genesis 3:15', 'Genesis', 3, 15, 'زه به داسې وکړم چې ته او دا ښځه به د یو بل څخه کرکه کوئ. ستا د نسل او د ښځې د نسل ترمنځ به تل دښمني وي. هغه به ستا سر ټکوي او ته به د هغه پونده چیچې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis3_verse_15.mp3', '', 1761754199, 1761754199),
(49850, 'Genesis 3:16', 'Genesis', 3, 16, 'څښتن خدای ښځې ته وویل: «د اولاد د زېږولو په وخت کې به ستا دردونه زیات کړم، خو ته به د مېړه شوق کوې او هغه به په تا باندې حکم چلوي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis3_verse_16.mp3', '', 1761754199, 1761754199),
(49851, 'Genesis 3:17', 'Genesis', 3, 17, 'څښتن آدم ته وویل: «دا چې تا د خپلې ښځې خبره اورېدلې ده او د هغې ونې مېوه دې وخوړله چې ما درته ویلي وو چې هغه ونه خورې، نو دا ځمکه ستا په سبب لعنتي شوه او ته به ټول عمر د هغې څخه په ډېر زحمت سره خوراک لاسته راوړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis3_verse_17.mp3', '', 1761754199, 1761754199),
(49852, 'Genesis 3:18', 'Genesis', 3, 18, 'ځمکه به هرزه بوټي او اغزي راشنه کوي او ته به ځنګلي بوټي خورې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis3_verse_18.mp3', '', 1761754199, 1761754199),
(49853, 'Genesis 3:19', 'Genesis', 3, 19, 'د خپل تندي په خولو باندې به خواړه تر‌لاسه کوې، تر هغه وخته پورې چې بېرته هغې خاورې ته وروګرځې د کومې څخه چې جوړ شوی یې، ځکه چې ته خاوره یې او بېرته به خاورې ته ورګرځې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis3_verse_19.mp3', '', 1761754199, 1761754199),
(49854, 'Genesis 3:20', 'Genesis', 3, 20, 'آدم په خپلې ښځې باندې حوا نوم کېښود ځکه چې هغه به د ټولو انسانانو مور وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis3_verse_20.mp3', '', 1761754199, 1761754199),
(49855, 'Genesis 3:21', 'Genesis', 3, 21, 'څښتن خدای د آدم او د هغه د ښځې دپاره د حیوان د پوستکي څخه کالي جوړ کړل او هغوی ته یې ورواغوستل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis3_verse_21.mp3', '', 1761754199, 1761754199),
(49856, 'Genesis 3:22', 'Genesis', 3, 22, 'څښتن خدای وویل: «اوس چې آدم زمونږ په شان شو چې ښه او بد پېژني، باید دا اجازه ورنه کړای شي چې د ژوندانه د ونې څخه مېوه وخوري او تر ابده پورې ژوندی پاتې شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis3_verse_22.mp3', '', 1761754199, 1761754199),
(49857, 'Genesis 3:23', 'Genesis', 3, 23, 'نو څښتن خدای دوی د عدن د باغ څخه وشړل چې لاړ شي او په هغې ځمکې باندې کار وکړي چې د هغې د خاورې څخه آدم جوړ شوی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis3_verse_23.mp3', '', 1761754199, 1761754199),
(49858, 'Genesis 3:24', 'Genesis', 3, 24, 'آدم یې وشاړه او د عدن د باغ لمرخاته خواته د ننوتلو په دروازه کې یې اسماني مخلوقات او هغه اور لرونکې توره چې هرې خواته به تاوېدله، ودرول، ترڅو څوک ونه شي کولای چې د ژوندانه ونې ته ورنژدې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis3_verse_24.mp3', '', 1761754199, 1761754199),
(49859, 'Job 16:1', 'Job', 16, 1, 'بيا ايُوب جواب ورکړو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job16_verse_1.mp3', '', 1761754199, 1761754199),
(49860, 'Job 16:2', 'Job', 16, 2, '”زۀ د دې څيزونو نه پخوا خبر يم، او ستاسو خبرې ما له تسلى نۀ راکوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job16_verse_2.mp3', '', 1761754199, 1761754199),
(49861, 'Job 16:3', 'Job', 16, 3, 'ستاسو د هوائى خبرو څۀ حد نشته څۀ؟ يا په څۀ وجه باندې تاسو خبرې نۀ بندوئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job16_verse_3.mp3', '', 1761754199, 1761754199),
(49862, 'Job 16:4', 'Job', 16, 4, 'کۀ تاسو زما په ځائ وئ نو هم ما ستاسو خِلاف لوئې لوئې خبرې جوړولے شوې، او ستاسو سپکاوے به مې کړے وے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job16_verse_4.mp3', '', 1761754199, 1761754199),
(49863, 'Job 16:5', 'Job', 16, 5, 'خو کۀ دا زۀ وے، نو ما به ستاسو حوصله افزائى کړے وے. او ما به دا کوشش کړے وے چې ستاسو غم لرې کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job16_verse_5.mp3', '', 1761754199, 1761754199),
(49864, 'Job 16:6', 'Job', 16, 6, 'خو کۀ زۀ د خپل ځان صفائى پېش کوم نو زۀ به په تکليف کښې کېږم، خو کۀ زۀ خبرې نۀ کوم نو ما ته بيا هم ډېر تکليف رارسيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job16_verse_6.mp3', '', 1761754199, 1761754199),
(49865, 'Job 16:7', 'Job', 16, 7, 'اے خُدايه پاکه، زۀ اوس تا ډېر ستومانه کړے يم، تا زما مکمل خاندان تباه کړے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job16_verse_7.mp3', '', 1761754199, 1761754199),
(49866, 'Job 16:8', 'Job', 16, 8, 'تا زۀ ګېر کړے يم، او دا زما خِلاف يو ثبوت دے، چې زۀ اوچ کلک او کمزورے شوے يم، او دا زما خِلاف ګواهى ورکوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job16_verse_8.mp3', '', 1761754199, 1761754199),
(49867, 'Job 16:9', 'Job', 16, 9, 'هغۀ د خپلې غصې په وجه زۀ خراب کړے يم او زما نه نفرت کوى، هغۀ ما ته خپل غاښونه چيچلى دى، زما دشمن د هغۀ سترګې زما خِلاف برندوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job16_verse_9.mp3', '', 1761754199, 1761754199),
(49868, 'Job 16:10', 'Job', 16, 10, 'خلق ما پورې خندا کوى، هغوئ په مسخرو کښې ما په مخ باندې وهى او زما خِلاف يې اتفاق کړے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job16_verse_10.mp3', '', 1761754199, 1761754199),
(49869, 'Job 16:11', 'Job', 16, 11, 'خُدائ پاک ما د خُدائ نه منکرو خلقو له ورکوى، او د بدعمله خلقو لاسونو ته مې حواله کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job16_verse_11.mp3', '', 1761754199, 1761754199),
(49870, 'Job 16:12', 'Job', 16, 12, 'زۀ صحيح سلامت وم او هغۀ زۀ دوه ټوټې کړم، هغۀ زۀ د څټ نه ونيولم او ټوټې ټوټې يې کړم، هغۀ زۀ د خپلې نښې په توګه ودرولم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job16_verse_12.mp3', '', 1761754199, 1761754199),
(49871, 'Job 16:13', 'Job', 16, 13, 'د هغۀ غشى ويشتونکى زما نه تاو شول. هغۀ زما ګردې راوويستلې او په ما يې هيڅ رحم ونۀ کړو، هغۀ زما تريخے په زمکه بهر وغورزولو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job16_verse_13.mp3', '', 1761754199, 1761754199),
(49872, 'Job 16:14', 'Job', 16, 14, 'هغۀ زۀ بيا مات رامات کړم، هغۀ د يو جنګيالى په شان په ما باندې رامنډه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job16_verse_14.mp3', '', 1761754199, 1761754199),
(49873, 'Job 16:15', 'Job', 16, 15, 'ما د ځان دپاره د ټاټ جامې ګنډلې دى، او هغۀ زۀ د خاورې په شان مېده کړے يم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job16_verse_15.mp3', '', 1761754199, 1761754199),
(49874, 'Job 16:16', 'Job', 16, 16, 'زما سترګې د ژړا نه سرې دى، او زما د سترګو ليمۀ تور شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job16_verse_16.mp3', '', 1761754199, 1761754199),
(49875, 'Job 16:17', 'Job', 16, 17, 'اګر چې ما هيڅ ظلم زياتے نۀ دے کړے، او زما په دُعا کښې خلوص دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job16_verse_17.mp3', '', 1761754199, 1761754199),
(49876, 'Job 16:18', 'Job', 16, 18, 'اے زمکې، زما وينه مۀ پټوه، او زما د اِنصاف فرياد دې څوک نۀ ختموى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job16_verse_18.mp3', '', 1761754199, 1761754199),
(49877, 'Job 16:19', 'Job', 16, 19, 'خو بيا هم په آسمان کښې داسې ذات شته چې هغه زما مل دے او هغه به بې‌شکه ووائى چې زۀ په حقه يم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job16_verse_19.mp3', '', 1761754199, 1761754199),
(49878, 'Job 16:20', 'Job', 16, 20, 'زما مينځګړے زما دوست دے او زما سترګې خُدائ پاک ته اوښکې تويوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job16_verse_20.mp3', '', 1761754199, 1761754199),
(49879, 'Job 16:21', 'Job', 16, 21, 'او زما دوست زما دپاره خُدائ پاک سره بحث کوى لکه څنګه چې يو سړے د خپل دوست دپاره مِنت زارى کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job16_verse_21.mp3', '', 1761754199, 1761754199),
(49880, 'Job 16:22', 'Job', 16, 22, 'صِرف يو څو کاله به پاتې وى چې زۀ به په هغه سفر باندې روان شم چې د هغې نه واپس کېدل نشته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job16_verse_22.mp3', '', 1761754199, 1761754199),
(49881, 'Esther 2:1', 'Esther', 2, 1, 'څه موده وروسته چې کله د خشایار پاچا قهر سوړ شو، هغه د وشتي، د هغه څه په اړه چې هغې کړي وو او د هغه فرمان په اړه چې د هغې په هکله یې ورکړی ؤ، فکر کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther2_verse_1.mp3', '', 1761754199, 1761754199),
(49882, 'Esther 2:2', 'Esther', 2, 2, 'نو د پاچا ځینو خدمتګارانو چې هغه ته نژدې خلک وو، وړاندیز وکړ: «د پاچا دپاره دې ښکلې پېغلې ولټول شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther2_verse_2.mp3', '', 1761754199, 1761754199),
(49883, 'Esther 2:3', 'Esther', 2, 3, 'پاچا دې د خپلې امپراتورۍ په هر ولایت کې مامورین وټاکي چې ټولې ښکلې پېغلې دې حرمسرای ته چې د شوش په بالاحصار کې دی، راولي. هغوی دې د هیجای تر څارنې لاندې وي چې د پاچا خصي شوی خدمتګار دی او د حرمسرای مسوول دی. هغوی ته دې د اړتیا وړ د سینګار شیان تیار کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther2_verse_3.mp3', '', 1761754199, 1761754199),
(49884, 'Esther 2:4', 'Esther', 2, 4, 'نو بیا هغه پېغله چې د پاچا خوښه شوه د وشتي په ځای دې ملکه شي.» دا مشوره د پاچا خوښه شوه او هماغسې یې وکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther2_verse_4.mp3', '', 1761754199, 1761754199),
(49885, 'Esther 2:5', 'Esther', 2, 5, 'د شوش په بالاحصار کې یو یهودي چې مردخای نومېده، اوسېده. هغه د بنیامین د قبیلې د یاییر زوی او د شمعي او قیس د اولادې څخه ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther2_verse_5.mp3', '', 1761754199, 1761754199),
(49886, 'Esther 2:6', 'Esther', 2, 6, 'هغه وخت چې د بابل پاچا نبوکدنصر د یهودا پاچا یهویاکین د ځینو یهودیانو سره د اسیرانو په توګه د اورشلیم څخه د ځان سره بوتلو، د مردخای نیکه هم د اسیرانو له جملې څخه ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther2_verse_6.mp3', '', 1761754199, 1761754199),
(49887, 'Esther 2:7', 'Esther', 2, 7, 'د مردخای د کاکا یوه لور وه چې هدسه نومېدله او د استر په نوم هم مشهوره وه. هغه ډېره ښایسته وه او ښکلی اندام یې درلود. کله چې د هغې مور او پلار مړه شول، نو مردخای هغه په فرزندۍ ونیوله او د خپلې لور په شان یې روزله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther2_verse_7.mp3', '', 1761754199, 1761754199),
(49888, 'Esther 2:8', 'Esther', 2, 8, 'نو کله چې د پاچا فرمان خپور شو، ډېرې پېغلې چې په هغو کې استر هم وه، د پاچا ماڼۍ ته چې د شوش په بالاحصار کې وه، راوستل شوې. هغوی د هیجای چې د حرمسرای مسوول ؤ، تر څارنې لاندې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther2_verse_8.mp3', '', 1761754199, 1761754199),
(49889, 'Esther 2:9', 'Esther', 2, 9, 'استر د هیجای په نظر کې ښه ښکاره شوه او هغه ورباندې مهربانه شو. هغه سمدلاسه د هغې دپاره د سینګار د شیانو او د ځانګړې ډوډۍ د تیارولو دپاره پروګرام جوړ کړ. د هغې دپاره یې اووه وینځې چې د پاچا د ماڼۍ څخه غوره شوې وې، وټاکلې او هغه یې د خپلو وینځو سره په حرمسرای کې ډېر ښه ځای ته بوتله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther2_verse_9.mp3', '', 1761754199, 1761754199),
(49890, 'Esther 2:10', 'Esther', 2, 10, 'د مردخای د لارښوونې له مخې استر دا خبره پټه ساتلې وه چې هغه په کومې کورنۍ او قوم پورې اړه لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther2_verse_10.mp3', '', 1761754199, 1761754199),
(49891, 'Esther 2:11', 'Esther', 2, 11, 'مردخای به هره ورځ د حرمسرای په مخکې ښکته او پورته ګرځېده، ترڅو پوه شي چې هغه څنګه ده او څه ورباندې پېښیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther2_verse_11.mp3', '', 1761754199, 1761754199),
(49892, 'Esther 2:12', 'Esther', 2, 12, 'د پېغلو دپاره د ښکلا تمرینونو پوره یو کال دوام ومونده: شپږ میاشتې یوازې په بدن باندې د مر د کنډ د غوړیو غوړول او شپږ میاشتې نور د عطرونو او د سینګار د شیانو دپاره. وروسته له دې یې هره پېغله په وار سره د خشایار پاچا حضور ته بېوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther2_verse_12.mp3', '', 1761754199, 1761754199),
(49893, 'Esther 2:13', 'Esther', 2, 13, 'کله چې یوه پېغله پاچا ته ورتلله، نو هغې کولای شول هرڅه چې یې غوښتل د حرمسرای څخه د پاچا ماڼۍ ته د ځان سره یوسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther2_verse_13.mp3', '', 1761754199, 1761754199),
(49894, 'Esther 2:14', 'Esther', 2, 14, 'هغه به ماښام ماڼۍ ته تلله، سهار به یې بل حرمسرای ته بېوله او د پاچا د وینځو د مسوول شعشغاز خصي تر څارنې لاندې به وه. بیا به پاچا ته نه ورتله، خو چې کله به د پاچا هغه خوښه شوه، نو هغه به یې په نوم راغوښتله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther2_verse_14.mp3', '', 1761754199, 1761754199),
(49895, 'Esther 2:15', 'Esther', 2, 15, 'استر د ابیحایل لور وه او د ده وراره مردخای هغه په فرزندۍ نیولې وه. کله چې د استر وار راورسېده چې پاچا ته ورشي، نو د هیجای د لارښوونې له مخې یوازې هغه څه چې یې ورته ویلي وو چې هغه یوسي، له ځان سره یې یووړل. هرچا چې هغه لیدله، هغه به یې خوښوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther2_verse_15.mp3', '', 1761754199, 1761754199),
(49896, 'Esther 2:16', 'Esther', 2, 16, 'په دې توګه د خشایار پاچا د پاچاهۍ د اووم کال په لسمه میاشت چې د طیبت میاشت وه، استر یې په شاهي ماڼۍ کې د پاچا حضور ته راوستله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther2_verse_16.mp3', '', 1761754199, 1761754199),
(49897, 'Esther 2:17', 'Esther', 2, 17, 'پاچا د نورو ټولو پېغلو نه د هغې سره زیاته مینه کوله او هغې د نورو ټولو پېغلو څخه د پاچا زیات پام او مهرباني تر لاسه کړه. د هغې په سر یې شاهي تاج کېښود او هغه یې د وشتي په ځای خپله ملکه جوړه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther2_verse_17.mp3', '', 1761754199, 1761754199),
(49898, 'Esther 2:18', 'Esther', 2, 18, 'بیا پاچا خپلو ټولو مامورینو او درباریانو ته د استر په ویاړ یوه لویه مېلمستیا جوړه کړه. هغه د ټولو ولایتونو دپاره دا ورځ د رخصتۍ ورځ اعلان کړه او شاهانه سوغاتونه یې خلکو ته ووېشل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther2_verse_18.mp3', '', 1761754199, 1761754199),
(49899, 'Esther 2:19', 'Esther', 2, 19, 'کله چې پېغلې د دوهم ځل دپاره راټولې شوې، مردخای د پاچا له خوا د ماڼۍ په یو مهم مقام کې ټاکل شوی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther2_verse_19.mp3', '', 1761754199, 1761754199),
(49900, 'Esther 2:20', 'Esther', 2, 20, 'استر دا خبره پټه ساتلې وه چې هغه په کومې کورنۍ او قوم پورې اړه لري، لکه څنګه چې مردخای هغې ته لارښوونه کړې وه. استر د خپل کوچنیوالي په شان د مردخای اطاعت کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther2_verse_20.mp3', '', 1761754199, 1761754199),
(49901, 'Esther 2:21', 'Esther', 2, 21, 'په هغو ورځو کې کله چې مردخای په ماڼۍ کې د پاچا خدمت کاوه، د پاچا د ماڼۍ دوه خصیان، بګتان او تارش چې د پاچا د کوټې د دروازې ساتونکي وو، په خشایار پاچا باندې په قهر شول او د هغه د قتل دسیسه یې جوړه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther2_verse_21.mp3', '', 1761754199, 1761754199),
(49902, 'Esther 2:22', 'Esther', 2, 22, 'خو مردخای د دې دسیسې څخه خبر شو او استر ملکې ته یې خبر ورکړ او هغې د مردخای له خوا دا خبره پاچا ته ورسوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther2_verse_22.mp3', '', 1761754199, 1761754199),
(49903, 'Esther 2:23', 'Esther', 2, 23, 'کله چې دغه خبر وڅېړل شو او ښکاره شوه چې رښتیا ده، نو پاچا دواړه خصیان په دار باندې وځړول. دا ټول د پاچا په حضور کې د امپراتورۍ د تاریخ په کتاب کې ولیکل شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther2_verse_23.mp3', '', 1761754199, 1761754199),
(49904, 'Isaiah 44:1', 'Isaiah', 44, 1, 'څښتن وایي: «ای یعقوبه خدمتګاره زما ای اسراییله چې غوره کړی یې ما اوس راته غوږ ونیسه»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah44_verse_1.mp3', '', 1761754199, 1761754199),
(49905, 'Isaiah 44:2', 'Isaiah', 44, 2, 'څښتن خالق دی ستا ته یې جوړ کړې د مور په ګېډه کې او وبه کړي درسره مرسته هغه داسې وایي: «ای یعقوبه خدمتګاره زما، مه وېرېږه ای اسراییله ته غوره کړې یې ما، مه وېرېږه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah44_verse_2.mp3', '', 1761754199, 1761754199),
(49906, 'Isaiah 44:3', 'Isaiah', 44, 3, 'ځکه تږې ځمکې ته به ورکړم زه اوبه او جاري به کړمه ویالې په وچه ځمکه باندې زه به نازل کړم خپل روح ستاسو اولادونو باندې او برکت به ور په برخه کړمه ستاسو اولادې ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah44_verse_3.mp3', '', 1761754199, 1761754199),
(49907, 'Isaiah 44:4', 'Isaiah', 44, 4, 'هغوی به لوی شي د واښو په منځ کې لکه د ولو په شان د هغو ولو په شان چې شنې کیږي د جاري ویالو په غاړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah44_verse_4.mp3', '', 1761754199, 1761754199),
(49908, 'Isaiah 44:5', 'Isaiah', 44, 5, 'ځینې به وایي چې مونږ یو د څښتن نور به یادوي خپل ځانونه د یعقوب په نامه ځینې به ولیکي خپلو لاسونو باندې چې مونږه یو د څښتن او نور به وایي چې مونږ یو اسراییلیان»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah44_verse_5.mp3', '', 1761754199, 1761754199),
(49909, 'Isaiah 44:6', 'Isaiah', 44, 6, 'څښتن، د اسراییلو پاچا او ژغورونکی مطلق قادر څښتن وایي داسې: «زه اول یم او اخر یم نشته بل خدای پرته له ما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah44_verse_6.mp3', '', 1761754199, 1761754199),
(49910, 'Isaiah 44:7', 'Isaiah', 44, 7, 'نشته څوک زما په شان که چېرې وي، هغه دې وکړي اعلان او په ترتیب سره دې وړاندې کړي خپل دلیلونه ماته چې ما یو قوم ځای په ځای کړی ؤ له ډېر پخوا نه هغوی دې ووایي چې څه پېښ شوي هغوی دې وکړي پېشګویي چې پېښېږي به څه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah44_verse_7.mp3', '', 1761754199, 1761754199);